import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import { promises as fs } from "fs";
import * as path from "path";

async function main() {
  try {
    // 1. Read the trial id
    const trialIdRaw = await fs.readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = trialIdRaw.trim();

    // Construct the source bucket name
    const normalizedTrialId = trialId.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
    const sourceBucketName = `harbor-seeded-${normalizedTrialId}`;

    // 2. Upload the files
    const s3 = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
        secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
      },
    });

    const files = ["a.txt", "b.txt", "c.txt"];
    for (const file of files) {
      const filePath = path.join(__dirname, "data", file);
      const fileContent = await fs.readFile(filePath);
      await s3.send(
        new PutObjectCommand({
          Bucket: sourceBucketName,
          Key: file,
          Body: fileContent,
        })
      );
      console.log(`Uploaded ${file} to ${sourceBucketName}`);
    }

    // 3. Call createForks
    console.log(`Creating forks from ${sourceBucketName}...`);
    const forkSet = await createForks(sourceBucketName, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (forkSet.error) {
      throw forkSet.error;
    }

    try {
      // 4. Write forks.json
      const forkNames = forkSet.forks.map(f => f.bucket);
      const forksJson = { forks: forkNames };
      await fs.writeFile(
        path.join(__dirname, "forks.json"),
        JSON.stringify(forksJson, null, 2),
        "utf-8"
      );
      console.log(`Wrote forks.json:`, forksJson);
    } finally {
      // 5. Call teardownForks
      console.log(`Tearing down forks...`);
      await teardownForks(forkSet);
      console.log(`Teardown complete.`);
    }

    // 6. Exit with status 0
    process.exit(0);
  } catch (error) {
    console.error("Error:", error);
    process.exit(1);
  }
}

main();

